const resolvers = {
  User: {
    name: (parent, args, ctx) => {
      if (!ctx.user?.permissions?.includes('VIEW_NAME') && ctx.tenantId !== parent.tenantId) {
        throw new Error('Forbidden')
      }
      return parent.name
    }
  }
}
